"""Generate out/w4-A.workflow.json from Brief A (written by hand from the brief)."""
import json, sys

BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1"
OUT = sys.argv[1]

HOLIDAYS = ["2026-10-26", "2026-11-11", "2026-11-26", "2026-12-25", "2027-01-01"]

# ---------------------------------------------------------------- code snippets (no double braces allowed)
DATE_HELPERS = r'''
import datetime, json
HOL = set(__HOL__)
WD = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
def isbd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def nth_bd_after(d, n):
    x = d
    c = 0
    while c < n:
        x = x + datetime.timedelta(days=1)
        if isbd(x):
            c += 1
    return x
def next_bd(d):
    return nth_bd_after(d, 1)
def lbl(d):
    return WD[d.weekday()] + ' ' + d.isoformat()
def last_bd_of_week(d):
    mon = d - datetime.timedelta(days=d.weekday())
    best = None
    for i in range(5):
        x = mon + datetime.timedelta(days=i)
        if isbd(x):
            best = x
    return best
def get_today():
    now = str(vars.get('now') or '').strip()
    try:
        dt = datetime.datetime.fromisoformat(now[:16])
    except Exception:
        try:
            dt = datetime.datetime.fromisoformat(now[:10] + 'T09:00')
        except Exception:
            dt = datetime.datetime(2026, 10, 14, 11, 0)
    return dt
'''.replace("__HOL__", repr(HOLIDAYS))

SETUP_CODE = DATE_HELPERS + r'''
try:
    dt = get_today()
    today = dt.date()
    vars['today_iso'] = today.isoformat()
    vars['today_label'] = lbl(today)
    vars['now_time'] = dt.strftime('%H:%M')
    nb = next_bd(today)
    vars['next_bd_label'] = lbl(nb)
    lines = []
    if dt.strftime('%H:%M') < '19:00':
        start = max(dt.strftime('%H:%M'), '10:00')
        lines.append('- today, ' + lbl(today) + ': any time later than ' + dt.strftime('%H:%M') + ' and from ' + start + ' to 19:00')
    lines.append('- the next business day, ' + lbl(nb) + ': any time from 10:00 to 19:00')
    vars['callback_window'] = chr(10).join(lines)
    cal = []
    for i in range(0, 29):
        x = today + datetime.timedelta(days=i)
        tag = 'business day' if isbd(x) else ('bank holiday, NOT a business day' if x.isoformat() in HOL else 'weekend, NOT a business day')
        extra = ' (today)' if i == 0 else ''
        cal.append('- ' + lbl(x) + extra + ': ' + tag)
    vars['calendar_text'] = chr(10).join(cal)
    mon = today - datetime.timedelta(days=today.weekday())
    wk = []
    for i in range(7):
        a = mon + datetime.timedelta(days=i)
        b = a + datetime.timedelta(days=7)
        wk.append('- "this ' + WD[i] + '" = ' + a.isoformat() + '; "next ' + WD[i] + '" = ' + b.isoformat())
    vars['weekday_map'] = chr(10).join(wk)
    vars['setup_state'] = 'ok'
except Exception as e:
    vars['setup_state'] = 'error'
    vars['today_iso'] = str(vars.get('now') or '')[:10]
    vars['today_label'] = str(vars.get('now') or '')
    vars['now_time'] = str(vars.get('now') or '')[11:16]
    vars['next_bd_label'] = 'the next business day'
    vars['callback_window'] = 'today later than now, or the next business day, from 10:00 to 19:00'
    vars['calendar_text'] = 'Business days are Monday to Friday except 2026-10-26, 2026-11-11, 2026-11-26, 2026-12-25, 2027-01-01.'
    vars['weekday_map'] = ''
'''

ACCOUNT_CODE = DATE_HELPERS + r'''
def money(v):
    try:
        f = float(v)
        return ('%.2f' % f)
    except Exception:
        return str(v)
def find_products():
    raw = vars.get('products_json')
    for cand in (raw, vars.get('products'), vars.get('get_account_response.data.products'), vars.get('fetch_account_response.data.products')):
        if isinstance(cand, list) and cand:
            return cand
        if isinstance(cand, str) and cand.strip().startswith('['):
            try:
                v = json.loads(cand)
                if isinstance(v, list) and v:
                    return v
            except Exception:
                pass
    items = {}
    for k, val in list(vars.items()):
        ks = str(k)
        if '.products.' in ks:
            rest = ks.split('.products.', 1)[1]
            parts = rest.split('.', 1)
            if len(parts) == 2 and parts[0].isdigit():
                items.setdefault(int(parts[0]), {})[parts[1]] = val
    return [items[i] for i in sorted(items)]
try:
    prods = find_products()
    dt = get_today()
    today = dt.date()
    if not prods:
        raise ValueError('no products')
    p = prods[0]
    typ = str(p.get('type') or '')
    if typ == 'credit_card':
        name = 'credit card ending ' + str(p.get('card_last4') or '')
        floor = p.get('minimum_payment')
        floor_name = 'minimum payment'
    elif typ == 'car_loan':
        name = 'car loan'
        floor = p.get('instalment_amount')
        floor_name = 'instalment amount'
    else:
        name = 'personal loan'
        floor = p.get('instalment_amount')
        floor_name = 'instalment amount'
    days = int(float(p.get('days_late') or 0))
    if days <= 7:
        band = 'early'
        deadline = nth_bd_after(today, 12)
        attempts = 1
    else:
        band = 'late'
        deadline = nth_bd_after(today, 7)
        attempts = 2
    lb = last_bd_of_week(today)
    if lb is None or lb <= today:
        a1 = last_bd_of_week(today + datetime.timedelta(days=7))
    else:
        a1 = lb
