# ---------------------------------------------------------------- tool builders
def api_tool(name, desc, fields, required, retries=0, mapping=None, post=None, pre=None):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    props.update(fields)
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": desc,
            "parameters": {
                "type": "object",
                "properties": {
                    "url": {"type": "string", "default": f"{BASE}/{name}"},
                    "method": {"type": "string", "default": "POST"},
                    "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                    "body": {"type": "object", "properties": props, "required": required},
                },
            },
        },
    }
    if mapping:
        t["response_mapping"] = mapping
    if post:
        t["post_process_code"] = post
    if pre:
        t["pre_process_code"] = pre
    return t


REASON_TABLE = ("promise (no reason): a promise was recorded. paid (no reason): customer says they already paid this amount. "
                "transferred + restructuring/human/support. no_promise + refused/hardship/dispute/service_error. "
                "not_verified + failed/declined. not_reached + callback/no_callback/wrong_number/deceased/unclear.")


def close_tool(outcomes, reasons, fixed_outcome=None, fixed_reason=None):
    out = {"type": "string", "enum": outcomes, "description": "How the call ended. One of: " + ", ".join(outcomes) + ". " + REASON_TABLE,
           "default": fixed_outcome if fixed_outcome else "{{outcome}}"}
    fields = {"outcome": out}
    if reasons is not None:
        rs = {"type": "string", "enum": reasons, "description": "Reason for the outcome. One of: " + ", ".join(reasons) + ". Leave it out for promise and paid.",
              "default": fixed_reason if fixed_reason else "{{reason}}"}
        fields["reason"] = rs
    desc = ("End the call in the bank's records. CALL it exactly once, at the very end, in the same message in which you thank the customer and say goodbye. "
            "Nothing can be done after it.")
    return api_tool("close_call", desc, fields, ["outcome"], pre=CLOSE_PRE)


def transfer_tool(queues):
    q = {"type": "string", "enum": queues, "description": "Queue. One of: " + ", ".join(queues) + ". restructuring = new payment plan or lower instalments; general = the customer insists on a human; support = hardship (illness, death in the family, job loss) and the customer accepted.",
         "default": "{{queue}}"}
    return api_tool("transfer_to_agent", "Hand the call to a person. CALL it only when the brief's transfer rule applies (see the task). Do not say the transfer is done before the result.",
                    {"queue": q}, ["queue"])


